<?php
namespace Database\Seeders;
use App\Models\HmsPermission;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\DB;
class HotelProductionSeeder extends Seeder{public function run():void{$items=['system.health'=>'View production health and queues','staff.operations'=>'Use staff operations mobile tools','notifications.manage'=>'Manage delivery notifications','backups.restore'=>'Restore verified backups'];foreach($items as $name=>$label){[$module]=explode('.',$name);HmsPermission::updateOrCreate(['name'=>$name],['label'=>$label,'module'=>$module]);}$grants=['super_admin'=>array_keys($items),'hotel_owner'=>['system.health','notifications.manage','backups.restore'],'general_manager'=>['system.health','notifications.manage'],'operations_manager'=>['staff.operations'],'housekeeping_manager'=>['staff.operations'],'restaurant_manager'=>['staff.operations'],'bar_manager'=>['staff.operations']];foreach($grants as $role=>$names){foreach($names as $name){$id=HmsPermission::where('name',$name)->value('id');DB::table('hms_role_permissions')->updateOrInsert(['role'=>$role,'permission_id'=>$id],['created_at'=>now(),'updated_at'=>now()]);}}}}
